Office.onReady(() => {});

const ZOHO_URL = "https://projects.zoho.in/"; // use your portal URL and data center

function openZoho(event) {
  try {
    // Opens the system browser directly, if this Outlook supports it
    Office.context.ui.openBrowserWindow(ZOHO_URL);
    event.completed();
  } catch (e) {
    // Fallback: a small dialog that immediately redirects to Zoho
    const redirectPage = "https://localhost:3000/assets/redirect.html?to=" + encodeURIComponent(ZOHO_URL);
    Office.context.ui.displayDialogAsync(redirectPage, { height: 80, width: 80 }, () => {
      event.completed();
    });
  }
}

Office.actions.associate("action", openZoho);